const TechSection = ({ sectionRef, techCardsRef, isRTL }) => (
  <section
    ref={sectionRef}
    className="py-20 sm:py-36 px-4 sm:px-8 relative overflow-hidden"
    style={{ background: 'linear-gradient(180deg, #000 0%, #040302 50%, #000 100%)' }}
  >
    {/* Ambient glow */}
    <div aria-hidden className="absolute top-1/4 left-1/4 w-[500px] h-[500px] rounded-full opacity-[0.02] blur-[100px] pointer-events-none"
      style={{ background: 'radial-gradient(circle, #d4af37 0%, transparent 70%)' }} />
    <div aria-hidden className="absolute bottom-0 right-1/4 w-[400px] h-[400px] rounded-full opacity-[0.015] blur-[80px] pointer-events-none"
      style={{ background: 'radial-gradient(circle, #d4af37 0%, transparent 70%)' }} />

    <div className={`max-w-7xl mx-auto relative z-10 ${isRTL ? 'text-right' : 'text-left'}`}>

      {/* ── Section header ── */}
      <div className="mb-16 sm:mb-20">
        <div className={`flex items-center gap-4 mb-6 ${isRTL ? 'flex-row-reverse' : ''}`}>
          <span className={`block w-10 h-px ${isRTL ? 'bg-gradient-to-l' : 'bg-gradient-to-r'} from-[#d4af37] to-transparent`} aria-hidden />
          <p className="text-[10px] tracking-[.1em] text-[#d4af37]/65 uppercase font-medium">
            {isRTL ? 'بنية تقنية للإنتاج' : 'Production-grade architecture'}
          </p>
        </div>
        <h2
          className={`text-3xl sm:text-5xl lg:text-6xl font-semibold leading-[1.08] mb-5 ${isRTL ? '' : 'tracking-tight'}`}
          style={{ letterSpacing: isRTL ? '0' : '-0.025em' }}
        >
          {isRTL ? 'تقنية تبني عليها' : 'Technology you can '}
          <span className="text-transparent bg-clip-text bg-gradient-to-r from-[#d4af37] to-white/70">
            {isRTL ? 'لسنوات قادمة.' : 'scale for years.'}
          </span>
        </h2>
        <p className="text-base sm:text-lg font-normal text-white/62 max-w-2xl leading-relaxed">
          {isRTL
            ? 'كل تقنية نختارها مُشغَّلة في الإنتاج بمشاريع حقيقية — لا تجارب، لا أدوات موسمية. تقنية تتوسع مع نمو أعمالك.'
            : 'Every technology we use is running in production on real projects — no experiments, no trend-chasing. Infrastructure that grows with your business.'}
        </p>
      </div>

      {/* ── Tech categories ── */}
      <div className="space-y-14 sm:space-y-20">
        {TECH_CATEGORIES.map((cat, ci) => (
          <div key={ci}>
            {/* Category label */}
            <p className={`text-[10px] tracking-[.3em] uppercase text-white/28 mb-5 flex items-center gap-3 font-light ${isRTL ? 'flex-row-reverse' : ''}`}>
              <span className="block w-5 h-px bg-white/12" aria-hidden />
              {isRTL ? cat.label.ar : cat.label.en}
            </p>

            {/* Tech grid */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
              {cat.items.map((tech, ti) => {
                const idx = ci * 4 + ti;
                return (
                  <div
                    key={tech.name}
                    ref={(el) => { if (techCardsRef.current) techCardsRef.current[idx] = el; }}
                    className="group relative flex items-center gap-4 p-4 sm:p-5 border border-white/[0.06] hover:border-[#d4af37]/35 transition-all duration-500 cursor-default overflow-hidden"
                    style={{ background: 'rgba(255,255,255,.015)' }}
                    onMouseEnter={(e) => { e.currentTarget.style.background = 'rgba(212,175,55,.025)'; }}
                    onMouseLeave={(e) => { e.currentTarget.style.background = 'rgba(255,255,255,.015)'; }}
                  >
                    {/* Bottom shine on hover */}
                    <div className="absolute bottom-0 left-0 right-0 h-px opacity-0 group-hover:opacity-100 transition-opacity duration-500"
                      style={{ background: 'linear-gradient(to right, transparent, rgba(212,175,55,.45), transparent)' }} />

                    {/* Icon */}
                    <div className="flex-shrink-0 text-white/40 group-hover:text-white/70 transition-colors duration-400">
                      <TechIcon name={tech.name} />
                    </div>

                    {/* Name + note */}
                    <div className="min-w-0">
                      <h3 className="text-sm sm:text-base font-medium text-white/65 group-hover:text-white/90 transition-colors duration-400 truncate">
                        {tech.name}
                      </h3>
                      <span className="text-[9px] tracking-wider uppercase text-white/22 group-hover:text-[#d4af37]/55 transition-colors duration-400 font-light">
                        {isRTL ? tech.note.ar : tech.note.en}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>

      {/* ── Stats row ── */}
      <div
        className={`mt-16 sm:mt-24 pt-10 border-t border-white/[0.05] grid grid-cols-3 gap-8 ${isRTL ? 'text-right' : 'text-left'}`}
      >
        {[
          ['12+', isRTL ? 'تقنية محورية'      : 'Core Technologies'],
          ['4+',  isRTL ? 'سنوات في الإنتاج'  : 'Years in Production'],
          ['50+', isRTL ? 'منتج مُسلَّم'       : 'Shipped Products'],
        ].map(([num, lbl]) => (
          <div key={lbl} className="group cursor-default">
            <div
              className="text-3xl sm:text-4xl font-bold text-[#d4af37] mb-1.5 transition-transform duration-300 group-hover:scale-105 origin-bottom"
              style={{ letterSpacing: '-0.03em', fontVariantNumeric: 'tabular-nums' }}
            >
              {num}
            </div>
            <div className="text-xs text-white/30 tracking-wide font-light">{lbl}</div>
          </div>
        ))}
      </div>

    </div>
  </section>
);

export default TechSection;
